def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D'
    if n == 2:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_def = op.count('D')
    my_def = my.count('D')

    if opp_def == 0:
        if my_def > 0:
            return 'D'
        return 'C'

    last_op = op[-1]
    last_my = my[-1]

    if last_op == 'D':
        if n >= 2 and my[-2] == 'D' and opp_def < n * 0.8:
            return 'C'
        return 'D'
    else:
        return 'C'
